function mergeTwoObjects (obj1, obj2) {
  const result = {...obj1};
  for (let p in obj2) {
    let a = obj2[p];
    if (obj2.hasOwnProperty (p) && typeof obj1[p] === 'object') {
      a = mergeTwoObjects (obj1[p], obj2[p]);
    }
    result[p] = a;
  }
  return result;
}

module.exports = function (styles1, styles2, stylesState = null) {
  return mergeTwoObjects (styles1, styles2);
};
